import os, sys
LAVA = ("The entire floor is real, glowing, bubbling molten lava, bright orange-red with black cooling crust, heat shimmer and drifting sparks, lighting everything from below; nobody touches the floor. ")
LOOK = ("Look: real film still from a big-budget modern action comedy, shot on 65mm film, real people, real locations, photoreal. "
        "Any visible text must be real words exactly as printed in a dictionary or a published newspaper.")
P = [
# 1 subway commute
"Cinematic photorealistic action comedy, the floor is lava and this time nobody is pretending. A crowded subway car during the morning commute. " + LAVA +
"Office workers in suits and coats stand balanced on the seats, hang from the overhead handrails with both hands, legs pulled up, one man calmly reading a folded newspaper while clinging to a vertical pole with his legs like a koala. A young woman in a business suit, high heels in one hand, leaps across the gap from one row of seats to the other at the exact moment the doors open, her coat flying. An old lady sits cross-legged on top of her rolling shopping trolley, unbothered, knitting. Camera: eye-level wide shot down the length of the car, 24mm lens, deep focus, the leaping woman frozen mid-air in the center. Lighting: harsh orange lava glow from below mixed with cold fluorescent subway lights above, long upward shadows. Color palette: lava orange, cold fluorescent white, steel grey, navy suits, fine film grain. " + LOOK,
# 2 supermarket
"Cinematic photorealistic action comedy, the floor is lava and this time nobody is pretending. A big bright supermarket aisle. " + LAVA +
"A father in a hoodie rides a shopping cart like a surfer, pushing off a shelf with a mop as a paddle, two delighted kids sitting in the cart holding a box of cereal. Ahead, a store clerk in a red apron stands on top of a shelf calmly restocking cans as if nothing were wrong, and a woman climbs along the freezer doors to reach the ice cream, her toes on the handle. Groceries that fell are sinking and sizzling in the lava. Camera: low dynamic shot from just above the lava at the end of the aisle, 24mm lens, deep focus, the surfing cart rushing toward camera in the center. Lighting: orange lava glow from below against bright white store lighting, sparks around the cart wheels. Color palette: lava orange-red, white shelves, colorful packaging, red apron, fine film grain. " + LOOK,
# 3 library
"Cinematic photorealistic adventure comedy, the floor is lava and this time nobody is pretending. A grand old library with towering wooden bookshelves. " + LAVA +
"An elderly librarian in a cardigan and reading glasses rides the rolling library ladder along the shelves at full speed, one hand on the ladder, the other holding a stack of returned books, her scarf flying, completely composed. Students sit reading on top of tall stacks of books like islands, feet tucked up, one boy carefully building his book stack taller as the lava rises. A single dropped paperback floats burning on the lava. Camera: eye-level wide shot across the reading room, 35mm lens, deep focus, the librarian on the rolling ladder in the left third, the book islands across the room. Lighting: warm orange lava glow from below on the old wood and gold book spines, soft green lamp glow above. Color palette: lava orange, dark mahogany wood, gold, deep green lamps, fine film grain. " + LOOK,
# 4 classroom, teacher keeps teaching
"Cinematic photorealistic comedy, the floor is lava and this time nobody is pretending. An ordinary elementary school classroom. " + LAVA +
"Twenty excited children in school uniforms jump from desk to desk, shrieking with joy, finally living their favorite game for real; one boy mid-air between two desks, arms spread like wings. At the front, the teacher stands calmly on top of her desk in sensible shoes, still teaching, pointing at the math on the blackboard with a long ruler, her coffee mug in the other hand, completely unimpressed. A goldfish bowl rests safely on a high shelf. Camera: eye-level wide shot from the back corner of the classroom, 24mm lens, deep focus, the leaping boy sharp in the foreground, the calm teacher at the back. Lighting: orange lava glow from below mixed with daylight from the windows. Color palette: lava orange, navy uniforms, green blackboard, yellow pencils, fine film grain. " + LOOK,
# 5 pizza delivery across the street
"Cinematic photorealistic action comedy, the floor is lava and this time nobody is pretending. A quiet residential street at dusk. " + LAVA +
"A determined pizza delivery rider in a red cap leaps across the street from one round manhole cover to the next like stepping stones, a tall stack of pizza boxes balanced perfectly in one arm, his body stretched mid-jump. Neighbors in bathrobes watch from their balconies and porch railings, one man holding out a cash tip on the end of a long fishing rod, a dog on a porch swing barking encouragement. Camera: low wide shot from just above the lava, 24mm lens, deep focus, the rider frozen mid-air in the center against the purple dusk sky. Lighting: intense orange lava light from below, warm porch lights, purple dusk above, glowing sparks. Color palette: lava orange-red, dusk purple, red cap, white pizza boxes, warm porch yellow, fine film grain. " + LOOK,
]
m = sys.argv[1] if len(sys.argv) > 1 else 'text2image_soul_v2'
d = 'v1'
os.makedirs(d, exist_ok=True)
open(f'{d}/prompts.txt', 'w', encoding='utf-8', newline='\n').write('\n'.join(P) + '\n')
open(f'{d}/model.txt', 'w').write(m + '\n')
open(f'{d}/aspect.txt', 'w').write('3:2\n')
print(m, [len(p.split()) for p in P])
